    // key geometry (playhead line at 72%; past above, scheduled-ahead below),
    // read-only, fixed height (no scrolling — the window slides with `now`).
    function _ambDrawVRollLive(cv, E, key, now) {
      const scroll = cv.parentElement;
      const w = ((scroll && scroll.clientWidth) || cv.clientWidth) | 0;
      const h = 160;
      if (!w) return;
      if (cv.width !== w) cv.width = w;
      if (cv.height !== h) { cv.height = h; cv.style.height = h + 'px'; }
      const ctx = cv.getContext('2d'); if (!ctx) return;
      ctx.clearRect(0, 0, w, h);
      const cap = (E.cap && E.cap[key]) || [];
      let P = 0; try { P = _ambLayerPeriodSec(E, key, _ambLayerByKey(E, key), E._cfg || (E.getCfg && E.getCfg())); } catch (e) {}
      const W = Math.max(1.5, Math.min(16, P || 1.5));
      const t0 = now - W * 0.72, t1 = now + W * 0.28;
      const rr = _ambPianoRangeFor(E, key);
      const g = _ambPianoKeyGeom(w, rr.LO, rr.HI);
      const A = (typeof masterFreqA === 'number') ? masterFreqA : 440;
      // Key-column guides (same look as the editable vertical roll).
      ctx.fillStyle = 'rgba(255,255,255,0.028)';
      for (const k of g.keys) if (k.black) ctx.fillRect(k.x0, 0, k.x1 - k.x0, h);
      ctx.strokeStyle = 'rgba(255,255,255,0.045)';
      ctx.beginPath();
      for (const k of g.keys) if (!k.black) { ctx.moveTo(k.x0 + 0.5, 0); ctx.lineTo(k.x0 + 0.5, h); }
      ctx.stroke();
      const yOf = (t) => ((t - t0) / (t1 - t0)) * h;
      // Playhead (horizontal, fixed at 72%).
      { const y = yOf(now); ctx.strokeStyle = 'rgba(255,255,255,0.22)'; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(0, y + 0.5); ctx.lineTo(w, y + 0.5); ctx.stroke(); }
      for (const e of cap) {
        if (!(e && e.freq > 0)) continue;
        const dur = Math.max(0.04, (e.dur || 100) / 1000);
        if (e.at + dur < t0 || e.at > t1) continue;
        let m = Math.round(69 + 12 * Math.log2(e.freq / A));
        const clamped = (m < g.LO || m > g.HI);
        m = Math.max(g.LO, Math.min(g.HI, m));
        const kx = g.centers[m];
        const kk = g.keys.find(q => q.m === m);
        const bw = kk ? Math.max(4, (kk.x1 - kk.x0) * (kk.black ? 0.9 : 0.62)) : 8;
        const y0 = Math.max(0, yOf(e.at)), y1 = Math.min(h, yOf(e.at + dur));
        const vol = (e.params && Number.isFinite(e.params.volume)) ? Math.max(0, Math.min(1, e.params.volume / 100)) : 0.8;
        ctx.fillStyle = 'rgba(127,214,196,' + ((clamped ? 0.2 : 0.3) + 0.6 * vol).toFixed(2) + ')';
        ctx.fillRect(kx - bw / 2, y0, bw, Math.max(3, y1 - y0));
      }
    }
    // Light each expanded piano's keys for the notes its layer is sounding at
    // `now` (audible clock). Intensity fades over the note's duration. Only open
    // pianos are touched (perf).
    function _ambUpdatePianos(E, now) {
      const host = document.getElementById(E.hostId); if (!host) return;
      const pianos = host.querySelectorAll('.ambient-piano.open'); if (!pianos.length) return;
      const A = (typeof masterFreqA === 'number') ? masterFreqA : 440;
      pianos.forEach(el => {
        const key = el.dataset.pkey; if (!key || !el._built) return;
        // Range/Register edits re-span the keyboard live (cheap no-op check).
        try { const r = _ambPianoRangeFor(E, key); _ambBuildPiano(el, r.LO, r.HI); } catch (e) {}
        try { _ambPianoHomeMark(E, key, el); } catch (e) {}
        const cap = (E.cap && E.cap[key]) || [];
        const lit = {};
        for (let i = cap.length - 1; i >= 0 && i >= cap.length - 96; i--) {
          const ev = cap[i]; if (!ev || !(ev.freq > 0)) continue;
          const dur = Math.max(0.05, (ev.dur || 200) / 1000);
          if (ev.at <= now && now < ev.at + dur) {
            const m = Math.round(69 + 12 * Math.log2(ev.freq / A));
            const rem = Math.max(0.3, 1 - (now - ev.at) / dur);
            if (!lit[m] || rem > lit[m]) lit[m] = rem;
          }
        }
        el.querySelectorAll('.ampk').forEach(k => {
          const m = +k.dataset.m, v = lit[m];
          if (v) { k.classList.add('lit'); k.style.setProperty('--lit', v.toFixed(2)); }
          else if (k.classList.contains('lit')) { k.classList.remove('lit'); k.style.removeProperty('--lit'); }
        });
      });
    }
    // ===== Per-layer EQ (#1) — live band meters + value sync ===========
    // Resolve the layer key for any control inside a layer card.
    function _ambKeyOfCard(lay) {
      if (!lay) return null;
      const kel = lay.querySelector('[data-nkey]') || lay.querySelector('[data-ukey]') || lay.querySelector('[data-ckey]');
      return kel ? (kel.dataset.nkey || kel.dataset.ukey || kel.dataset.ckey) : (lay.dataset.inst || null);
    }
    // Light each OPEN EQ panel's band meters by that band's energy, from the
    // layer's FFT analyser (continuous: louder → more intense, hue shifts up).
    function _ambUpdateEqMeters(E) {
      const host = document.getElementById(E.hostId); if (!host) return;
      const panels = host.querySelectorAll('details.ambient-eq[open]'); if (!panels.length) return;
      panels.forEach(d => {
        const key = _ambKeyOfCard(d.closest('.ambient-layer')); if (!key) return;
        const e = E.mod && E.mod[key]; if (!e || (!e.vca && !e.core)) return;
        // Lazy: this panel is open, so the layer needs its analyser now. Tap the VCA
        // (a sink — doesn't alter the signal path); it stays until the layer is torn
        // down. Layers whose EQ panel is never opened never pay for one.
        // CORE STRIPS: no node VCA — tap the slot output instead (post-strip).
        let an = e.eqAnalyser;
        if (!an) {
          try {
            an = e.eqAnalyser = new Tone.Analyser('fft', 64);
            if (e.core) e.core.tap(an); else e.vca.connect(an);
          } catch (x) { return; }
        }
        let data; try { data = an.getValue(); } catch (x) { return; }
        const n = data && data.length; if (!n) return;
        const loEnd = Math.max(1, Math.floor(n * 0.12)), midEnd = Math.max(loEnd + 1, Math.floor(n * 0.5));
        const avg = (a, b) => { let s = 0, c = 0; for (let i = a; i < b && i < n; i++) { const v = data[i]; if (isFinite(v)) { s += v; c++; } } return c ? s / c : -120; };
        const norm = (db) => Math.max(0, Math.min(1, (db + 90) / 78));   // ~-90..-12 dB → 0..1
        const bands = { low: norm(avg(0, loEnd)), mid: norm(avg(loEnd, midEnd)), high: norm(avg(midEnd, n)) };
        d.querySelectorAll('.ambient-eq-meter').forEach(m => { m.style.setProperty('--e', (bands[m.dataset.band] || 0).toFixed(2)); });
      });
    }
    // Set each EQ slider + dB readout from the layer's stored eq (on build/restore).
    function _ambSyncEq(E) {
      const host = document.getElementById(E.hostId); if (!host) return;
      host.querySelectorAll('.ambient-eq-sl').forEach(sl => {
        const key = _ambKeyOfCard(sl.closest('.ambient-layer')); if (!key) return;
        const L = _ambLayerByKey(E, key);
        const b = sl.dataset.band, v = (L && L.eq && Number.isFinite(L.eq[b])) ? (L.eq[b] | 0) : 0;
        sl.value = String(v);
        const db = sl.parentNode && sl.parentNode.querySelector('.ambient-eq-db[data-band="' + b + '"]'); if (db) db.textContent = (v > 0 ? '+' : '') + v;
      });
    }
    // Mark the currently-playing When cell for the layer that owns playhead `el`.
    // `cycle` is the audible iteration count; the live cell is cycle % length.
    function _ambPaintWhenCursor(el, active, cycle) {
      const layEl = el.closest && el.closest('.ambient-layer');
      const grid = layEl && layEl.querySelector('.ambient-when-grid');
      if (!grid) return;
      const cells = grid.querySelectorAll('.ambient-when-cell');
      const n = cells.length;
      if (!n) return;
      const cur = (active && cycle >= 0) ? (((cycle % n) + n) % n) : -1;   // <0 = pre-onset lead → no highlight
      if (grid._ambCurIdx === cur) return;            // unchanged → no DOM churn
      if (grid._ambCurIdx >= 0 && cells[grid._ambCurIdx]) cells[grid._ambCurIdx].classList.remove('cur');
      if (cur >= 0 && cells[cur]) cells[cur].classList.add('cur');
      grid._ambCurIdx = cur;
    }
    function _ambVizKick(E) { if (E.viz && !E.viz.raf) E.viz.raf = requestAnimationFrame(() => _ambVizFrame(E)); }
    function _ambStartViz(E) {
      if (E.viz) { _ambVizFrame(E); return; }
      // The spectrum analyser/canvas are OPTIONAL (the master Bloom has no canvas).
      // Still start E.viz + the rAF regardless, because _ambVizFrame also drives the
      // layer bars, elapsed time, note lines and live rolls — those must run with or
      // without a visualizer.
      const canvas = document.getElementById(E.vizId);
      let analyser = null;
      if (canvas && typeof Tone !== 'undefined') {
        try {
          analyser = new Tone.Analyser('waveform', 512);
          if (typeof masterBus !== 'undefined' && masterBus) masterBus.connect(analyser);
          else Tone.getDestination().connect(analyser);
        } catch (e) { analyser = null; }
      }
      E.viz = { analyser, raf: 0 };
      _ambVizFrame(E);
    }
    function _ambStopViz(E) {
      if (!E.viz) return;
      if (E.viz.raf) cancelAnimationFrame(E.viz.raf);
      try { E.viz.analyser.dispose(); } catch (e) {}
      E.viz = null;
    }

    // ---- Panel ---------------------------------------------------------
    function _ambFmtMs(ms) {
      ms = ms | 0;
      return ms >= 1000 ? (ms / 1000).toFixed(2).replace(/0$/, '').replace(/\.0?$/, '') + ' s' : ms + ' ms';
    }
    function _ambRefreshPlayBtn(E) {
      const btn = document.getElementById(E.playId);
      if (!btn) return;
      const on = !!E.timer;
      btn.textContent = on ? '⏹' : '▶';   // icon-only, like the Make footer play button
      btn.classList.toggle('active', on);
    }
    // ---- Shared control builders (module scope: used by _ambientInit AND the
