          '<button type="button" class="ambient-arp-add" id="' + p + '-arp-add" title="Add a scale / chord to the series">+ Add</button>' +
        '</div>' +
        '<div class="ambient-arp-list" id="' + p + '-arp-list"></div>' +
      '</div>';
